PREFIX envthes: <http://vocabs.lter-europe.net/EnvThes/>
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX qudt: <http://qudt.org/schema/qudt/>

SELECT ?year
WHERE {
  GRAPH <hydroturtle/quadica> {
    {
      SELECT ?year (MEDIAN(?q) AS ?nationalMedian)
      WHERE {
        ?s rdf:type envthes:30212 .
        ?s hyobs:fractionAreaInGermany ?frac .
        ?sosa sosa:hasFeatureOfInterest ?s ;
              sosa:observedProperty hyobs:DischargeMedian ;
              sosa:resultTime ?year ;
              sosa:hasResult ?qval .
        ?qval qudt:numericValue ?q .
      }
      GROUP BY ?year
    }
    {
      SELECT (MEDIAN(?q) AS ?longTermMedian)
      WHERE {
        ?s rdf:type envthes:30212 .
        ?s hyobs:fractionAreaInGermany ?frac .
        ?sosa sosa:hasFeatureOfInterest ?s ;
              sosa:observedProperty hyobs:DischargeMedian ;
              sosa:resultTime ?anyYear ;
              sosa:hasResult ?qval .
        ?qval qudt:numericValue ?q .
      }
    }
    FILTER(?nationalMedian < ?longTermMedian)
  }
}

actual_sparql:
PREFIX hyobs: <https://w3id.org/hmontology/>
PREFIX sosa:  <http://www.w3.org/ns/sosa/>
PREFIX qudt:  <http://qudt.org/schema/qudt/>
PREFIX xsd:   <http://www.w3.org/2001/XMLSchema#>

SELECT ?year ?nationalMedianQ ?longTermMedianQ
WHERE {
  GRAPH <hydroturtle/quadica> 
  {
    {
      SELECT ?year (AVG(xsd:decimal(?val)) AS ?nationalMedianQ)
      WHERE {
        ?obs a sosa:Observation ;
            sosa:observedProperty hyobs:DischargeMedian ;
            sosa:resultTime ?t ;
            sosa:hasResult ?res .
        ?res qudt:numericValue ?val .
        BIND(YEAR(?t) AS ?year)
      }
      GROUP BY ?year
    }
    {
      SELECT (AVG(xsd:decimal(?val2)) AS ?longTermMedianQ)
      WHERE {
        ?obs2 a sosa:Observation ;
              sosa:observedProperty hyobs:DischargeMedian ;
              sosa:hasResult ?res2 .
        ?res2 qudt:numericValue ?val2 .
      }
    }

    FILTER(?nationalMedianQ < ?longTermMedianQ)
  }
}
ORDER BY ?year

